"""Propose own-native static leaf samples separately from animation alpha and wood."""
import json,hashlib,math
from pathlib import Path
import numpy as np
from PIL import Image,ImageDraw,ImageFilter
R=Path(__file__).resolve().parents[3];B=R/'level-editor/work/croisement03-refinement';O=B/'restart2/tree01-static-leaf-proposal-v1';S=math.sin(math.radians(35));C=math.cos(math.radians(35))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 source=B/'baseline/covered.png';fragment=B/'restart2/tree01-native-fragment-v1';wood=B/'restart2/tree01-cpu-complete-wood-v3/geometry.json';d=json.loads(wood.read_text());domain=np.array(Image.open(fragment/'spatial-proposal.png'))>0;union=np.array(Image.open(fragment/'alpha-union.png'))>0;reserved=Image.new('L',(175,175));draw=ImageDraw.Draw(reserved)
 for part in d['parts']:
  v=np.array(part['vertices']);p=np.column_stack((v[:,0],-v[:,1]*S-v[:,2]*C))
  for face in part['faces']:draw.polygon([tuple(p[i])for i in face],fill=255)
 near=np.array(Image.fromarray(union.astype('uint8')*255).filter(ImageFilter.MaxFilter(3)))>0;rgb=np.array(Image.open(source).convert('RGB').crop((0,0,175,175))).astype('int16');gold=(rgb[:,:,0]-rgb[:,:,2]>=25)&(rgb[:,:,1]-rgb[:,:,2]>=15)&(rgb[:,:,0]>=rgb[:,:,1]*.8);candidate=domain&near&~union&gold&~(np.array(reserved)>0);O.mkdir(exist_ok=False);Image.fromarray(candidate.astype('uint8')*255).save(O/'candidate.png');reserved.save(O/'excluded-wood-projection.png');rgba=np.dstack((rgb.astype('uint8'),candidate.astype('uint8')*255));Image.fromarray(rgba).save(O/'proposed-source-rgba.png');marked=rgb.astype('uint8').copy();marked[union]=[255,0,180];marked[candidate]=[0,220,255];marked[(np.array(reserved)>0)&domain]=[100,100,255];sheet=Image.new('RGB',(350,175));sheet.paste(Image.fromarray(rgb.astype('uint8')));sheet.paste(Image.fromarray(marked),(175,0));sheet.resize((1050,525),Image.Resampling.NEAREST).save(O/'source-proposal-comparison.png');report={'status':'PRIVATE_SOURCE_PROPOSAL_REQUIRES_DIRECT_REVIEW','source_sha256':sha(source),'fragment_scope_sha256':sha(fragment/'scope.json'),'wood_sha256':sha(wood),'native_box':[0,0,175,175],'native_union_pixels':int(union.sum()),'candidate_static_pixels':int(candidate.sum()),'wood_projection_pixels':int((np.array(reserved)>0).sum()),'method':'Gold native source samples within one pixel of original14frame alpha union, outside that union and projected four-track wood; spatial gold-crown proposal only.','limits':['Alpha adjacency/color are proposals, not proof of ownership; direct source inspection required.','May include fine native twigs or distant foliage; uncertain samples must remain unassigned.','No occupancy mask substituted for RGBA, no API or terrain edit.','Accepted additional native samples require fresh geometry/input scope before publication/fill.']};(O/'scope.json').write_text(json.dumps(report,indent=2)+'\n');print({'candidate_pixels':int(candidate.sum()),'known_union':int(union.sum())})
if __name__=='__main__':main()
